import{_ as a,o as t,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Provenance & Authority","description":"","frontmatter":{},"headers":[],"relativePath":"reference/08-provenance-and-authority.md","filePath":"reference/08-provenance-and-authority.md","lastUpdated":1788530310000}'),n={name:"reference/08-provenance-and-authority.md"};function o(s,e,c,d,l,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="provenance-authority" tabindex="-1">Provenance &amp; Authority <a class="header-anchor" href="#provenance-authority" aria-label="Permalink to &quot;Provenance &amp; Authority&quot;">​</a></h1><p>This is the trust contract for every astrological statement made by the project. A computed fact, a textual rule, a regional convention, and a project heuristic are different kinds of claim. None inherits the authority of another merely because they appear in the same response.</p><p>The machine-readable companion is <a href="provenance.json"><code>provenance.json</code></a>. Tests validate its vocabulary, identifiers, source references, and evidence gaps.</p><h2 id="evidence-classes" tabindex="-1">Evidence classes <a class="header-anchor" href="#evidence-classes" aria-label="Permalink to &quot;Evidence classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Meaning</th><th>Suitable user-facing language</th></tr></thead><tbody><tr><td><code>astronomical</code></td><td>Computed from an ephemeris or documented astronomical algorithm</td><td>&quot;computed&quot;, with system and ayanamsa</td></tr><tr><td><code>textual</code></td><td>A rule attested in an identified textual edition at a precise locator</td><td>&quot;according to [text/tradition]&quot;</td></tr><tr><td><code>published_panchangam</code></td><td>Compared with a named external panchangam for a date and place</td><td>&quot;externally verified&quot; only for the recorded cells</td></tr><tr><td><code>regional_convention</code></td><td>A living or regional practice that is not universal</td><td>&quot;in the configured Telugu/South Indian tradition&quot;</td></tr><tr><td><code>project_heuristic</code></td><td>A product scoring or presentation choice</td><td>&quot;project score/rank&quot;, never &quot;scripturally ordained&quot;</td></tr></tbody></table><h2 id="verification-states" tabindex="-1">Verification states <a class="header-anchor" href="#verification-states" aria-label="Permalink to &quot;Verification states&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>verified</code></td><td>Evidence has been inspected and a precise locator or comparison record exists</td></tr><tr><td><code>partially_verified</code></td><td>Some representative cases or part of the claim have been checked</td></tr><tr><td><code>engine_pinned</code></td><td>A regression test preserves current output; it is not independent verification</td></tr><tr><td><code>needs_locator</code></td><td>A plausible authority is known, but chapter/verse/page is not yet recorded</td></tr><tr><td><code>heuristic</code></td><td>Intentionally a product judgment, not a textual claim</td></tr><tr><td><code>contradicted</code></td><td>Inspected evidence materially conflicts with configured behavior; the profile must not be called verified</td></tr></tbody></table><h2 id="source-editions" tabindex="-1">Source editions <a class="header-anchor" href="#source-editions" aria-label="Permalink to &quot;Source editions&quot;">​</a></h2><p>The register identifies editions rather than citing titles alone. Page numbers must always be interpreted against the named edition.</p><ul><li><strong>BS-IYER-1884</strong> — Varahamihira, <em>The Brihat Samhita</em>, translated by N. Chidambaram Iyer, South Indian Press, 1884. Public scan: <a href="https://archive.org/details/b29353130" target="_blank" rel="noreferrer">https://archive.org/details/b29353130</a>.</li><li><strong>BS-SASTRI-BHAT-1946</strong> — Varahamihira, <em>Brihat Samhita</em>, Sanskrit text and English translation by V. Subrahmanya Sastri and M. Ramakrishna Bhat, 1946. Public scan: <a href="https://archive.org/details/Brihatsamhita" target="_blank" rel="noreferrer">https://archive.org/details/Brihatsamhita</a>.</li><li><strong>BVR-MUHURTHA-1993</strong> — B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, UBS Publishers&#39; Distributors, 1993, ISBN 9788185674681. This is a modern synthesis and secondary authority, not scripture. The Bhumi Puja / house- foundation profile uses Chapter XII, printed page 50 (PDF page 54), from the inspected public scan linked in the machine-readable register.</li><li><strong>MC-HINDI-IA</strong> — Rama Daivajna, <em>Muhurta Chintamani</em>, Sanskrit text with Hindi commentary, undated public scan. Verse numbers and printed pages are stable in the registered Internet Archive object, but the scan does not expose publisher/date metadata; citations disclose that limitation.</li><li><strong>DP-DAY-PAGE</strong> — Drik Panchang day/festival pages for a recorded city and date. This is an external published-panchangam comparison surface, not a textual authority for every project rule.</li><li><strong>SWISSEPH</strong> — Astrodienst, <em>Swiss Ephemeris 2.10 Programmer&#39;s Documentation</em>, together with the repository&#39;s pinned <code>pyswisseph</code> runtime. The registered claims cite the relevant API sections. This supports astronomical positions and event models, not interpretive judgments.</li><li><strong>SS-BURGESS-WHITNEY-1860</strong> — Ebenezer Burgess, edited with notes by William Dwight Whitney, <em>Translation of the Surya-Siddhanta: A Text-Book of Hindu Astronomy</em>, <em>Journal of the American Oriental Society</em> 6 (1860), pp. 141–498. The engine contract records chapter, verse and edition-page locators against this edition.</li></ul><p>Generic references to Dharmasindhu, BPHS and other editions of the named texts still require edition-level normalization. Registering one exact edition for one claim does not automatically verify every rule that cites the same title. Until an edition and locator are recorded for the specific claim, it remains <code>needs_locator</code>.</p><h2 id="current-ledger-summary" tabindex="-1">Current ledger summary <a class="header-anchor" href="#current-ledger-summary" aria-label="Permalink to &quot;Current ledger summary&quot;">​</a></h2><ul><li>Drik astronomical positions are computed from Swiss Ephemeris and have representative external comparisons.</li><li>The 2027–2028 forward-festival fixture contains <strong>1 DP-verified cell and 29 engine-pinned cells</strong>. Engine-pinned means regression-protected, not independently verified.</li><li>The seven classical Gochara favourable-house sets have an exact Brihat Samhita 104.4 locator. Vedha mappings and exemptions are independently verified against Phaladeepika 26.3–8 and Jataka Parijata Volume III. Phaladeepika 26.2 supports the configured node houses 3, 6, 10 and 11 by treating Rahu and Ketu like Surya; node Vedha remains unverified. Its 26.1 and 26.22–23 verify the Moon-sign reference and underlying adverse Shani houses, but not the product&#39;s conventional names or phase labels.</li><li>Daily website prose has its own <code>daily_horoscope.llm_interpretation</code> claim. Only its declared transit triples are engine-verified; prose and advice stay <code>heuristic</code> even when every cited calculation is correct.</li><li>Muhurtam activity rules, Panchanga Shuddhi, and several dosha/yoga tables still have source work recorded at their actual verification state.</li><li>Bhumi Puja / foundation laying is an activity-level exception: its profile has a page-level locator and criterion-by-criterion implementation crosswalk. Full election-chart and site-placement conditions remain visible manual checks.</li><li>Well digging has the same activity-level treatment: the admitted Nakshatras and rising Rasis are automated from Chapter XII, while planetary Kendra and water-quality conditions remain explicit practitioner checks.</li><li>The former generic “Property / Land purchase” option is now scoped narrowly to buying land for building, matching Raman&#39;s separate treatment of land and completed houses. Its weekday, Nakshatra and Rikta-Tithi rules have a precise Chapter XII locator; the Drik browser also post-screens three deterministic Guru/Kuja predicates while lordship relationships remain manual.</li><li>Namakarana now has a Chapter VIII rule-level profile: its Nakshatra, weekday and rejected-Tithi lists are automated, while birth-day timing and election-chart/name criteria remain visible manual checks.</li><li>Annaprasana has a Chapter VIII profile cross-referenced to Chapter V&#39;s general Panchanga-Suddhi Tithis; the Drik browser post-screens the vacant 10th and three named Graha-house exclusions, while age-month and qualitative Lagna requirements remain explicit manual prerequisites.</li><li>Karnavedha now enforces Raman&#39;s daytime-only instruction across the Python and MCP night-slot path, plus exact weekday, Tithi and rising-Rasi gates; age, transition and election-house checks remain manual.</li><li>Mundana/Chaula now enforces Shukla Paksha, non-combust Guru/Shukra, exact Tithi/Nakshatra/weekday/Lagna criteria and a cross-surface solar-noon cutoff; age, pregnancy, seasonal wording and chart placements remain manual.</li><li>Vidyarambha/Aksharabhyasa now has exact weekday, Nakshatra and movable-or-common Lagna gates; age, time preference and chart requirements remain visible manual checks.</li><li>Upanayana now preserves Paksha-specific Tithis by exact name and enforces lunar-month, Uttarayana solar-Rasi, weekday, Nakshatra, Lagna and before-noon gates; age, conditional combustion and full chart judgment remain manual.</li><li>Vehicle purchase has a deliberately narrow verified Chapter IV preference: five movable Nakshatras receive +1. Its other ranking preferences remain uncited project rules rather than inheriting that claim&#39;s authority.</li><li>Absolute score thresholds and relative ordering are project heuristics.</li></ul><p>Activity-level coverage is tracked separately in <a href="./16-activity-provenance-coverage">Muhurtam Activity Provenance Coverage</a>. The browser-only chart and personal-role subset is documented independently in <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>; it does not give Python/MCP or the unresolved qualitative clauses a stronger verification state.</p><p>The candidate-time calculation has a deliberately split authority boundary. DashaFlow supplies Lahiri planetary Rashi and degree facts. The selected-city <code>lagna.json</code> data—generated and validated from this repository&#39;s frozen Drik/Lahiri calculation—supplies the canonical Lagna for each sampled civil minute, and the browser recomputes every Whole Sign house from those two facts. Sidecar Lagna and house fields are diagnostic only. Around a known local Lagna transition, a five-minute guard prevents the documented Drik Panchang/DashaFlow minute-level convention difference from becoming a false automated verdict: partially overlapping windows retain Lagna-dependent rules as <code>unknown</code> for review. This is a computation-assurance policy, not new textual authority for the underlying electional rule.</p><p>It currently records <strong>34 verified canonical profiles, no contradicted profiles and 1 explicit project heuristic across all 35 canonical profiles</strong>. The accepted API catalogue also has the legacy <code>litigation</code> alias for <code>court</code>, so there are 36 accepted keys; aliases are not counted as distinct elections. No activity remains implicitly covered by a title-level citation. <code>tools/check_activity_provenance.py</code> enforces verified, contradicted and heuristic links against the ledger and fails if a profile has no explicit disposition.</p><h2 id="citation-acceptance-rule" tabindex="-1">Citation acceptance rule <a class="header-anchor" href="#citation-acceptance-rule" aria-label="Permalink to &quot;Citation acceptance rule&quot;">​</a></h2><p>A claim may move to <code>verified</code> only when its ledger entry contains:</p><ol><li>a stable claim identifier;</li><li>an evidence class;</li><li>a named source edition;</li><li>a chapter, verse, table, or edition-specific page locator;</li><li>a short scope note stating what the citation does—and does not—support;</li><li>a maintainer review date.</li></ol><p>For a published-panchangam comparison, replace items 3–4 with the page URL, city, date, captured values, tolerance, and date inspected.</p><h2 id="product-language-rule" tabindex="-1">Product-language rule <a class="header-anchor" href="#product-language-rule" aria-label="Permalink to &quot;Product-language rule&quot;">​</a></h2><ul><li>Display facts as facts: &quot;Moon enters Karka at 14:32.&quot;</li><li>Attribute doctrine: &quot;For Vivaha, this configuration is avoided in the configured Muhurta tradition.&quot;</li><li>Disclose convention: &quot;Some South Indian traditions observe this rule.&quot;</li><li>Label heuristics: &quot;Best available project score,&quot; not &quot;Excellent Muhurtam,&quot; unless it also clears the absolute quality threshold.</li><li>Medical, legal, and financial timing is supplementary cultural guidance and never a substitute for qualified professional advice.</li></ul>',22)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
